def web_server_module(name, instance_type="t2.micro", region="us-east-1"):
    return {
        "name": name,
        "resource": "aws_instance",
        "instance_type": instance_type,
        "region": region,
    }


dev = web_server_module("dev-web")
prod = web_server_module("prod-web", instance_type="m5.large")

for server in (dev, prod):
    print(server)
